-- 標準レシピの出所確認。家庭内の料理・副菜・朝食設定・保存済み献立は更新しない。

-- 元レシピと工程は削除せず保留し、独立したIDで差し替えを追加する。

create temporary table reviewed_recipe_seed (item jsonb not null) on commit drop;

insert into reviewed_recipe_seed values ('[{"key":"P01","id":"5d875c07-70a0-5089-b24c-a17c51542b76","name":"なすと豚肉のしょうが蒸し","proteinSource":"meat","servings":4,"totalMinutes":30,"ingredients":["【主菜】なす 3本（約300g）・豚薄切り肉 400g・しょうが 15g","【蒸し汁】水 150ml・酒 大さじ2","【仕上げ】醤油 大さじ2・酢 大さじ1・砂糖 小さじ2"],"steps":["しょうがは皮を洗って細切りにする。なすはへたを除き、縦半分にしてから厚さ1cmの斜め切りにする。","深さのあるフライパンになすを広げ、豚肉を重なりすぎないようにのせる。しょうが、水、酒を加える。","ふたをして中火にかける。蒸気が出たら弱めの中火にし、10分ほど加熱する。途中で水がなくなりそうなら水を少量ずつ足す。","肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。 なすの中心までやわらかくなったら火を止める。","醤油、酢、砂糖を小鉢で混ぜる。蒸した具を皿に分け、たれを回しかける。"],"notes":[],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P02","id":"006de8a6-028d-5bb6-9bf0-52dab9a61894","name":"ぶりのしょうが照り焼き","proteinSource":"fish","servings":4,"totalMinutes":25,"ingredients":["【主菜】ぶり 4切れ（約400g）・しょうが 15g・油 小さじ2","【たれ】醤油 大さじ2・みりん 大さじ2・酒 大さじ2・水 大さじ2・砂糖 小さじ2"],"steps":["しょうがを薄切りにする。ぶりの表面の水分をペーパーで拭く。たれの材料を別の器で混ぜる。","フライパンに油を入れて中火で温め、ぶりを並べる。片面を3分ほど焼き、裏返して2分ほど焼く。","余分な脂をペーパーで取り、しょうがとたれを入れる。煮立ったら弱火にしてふたをし、5分ほど煮る。","身の厚い部分まで火が通ったことを確認する。火が通っていなければ水を少量足して加熱を続ける。","ふたを外し、たれをスプーンでかけながら1〜2分煮詰める。たれが焦げる前に火を止め、皿に盛る。"],"notes":[],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P03","id":"994b0da4-5db6-5eb1-afee-e722b6137bb1","name":"豚肉と長ねぎのカレーうどん","proteinSource":"noodle","servings":4,"totalMinutes":30,"ingredients":["【主菜】ゆでうどん 4玉・豚薄切り肉 300g・長ねぎ 2本","【汁】だし汁 1200ml・カレー粉 大さじ2・醤油 大さじ3・みりん 大さじ2","【とろみ】片栗粉 大さじ2・水 大さじ4"],"steps":["長ねぎは厚さ1cmの斜め切り、豚肉は食べやすい長さに切る。片栗粉と水を小鉢で混ぜておく。","鍋にだし汁と長ねぎを入れて中火にかける。沸いたら豚肉をほぐしながら加え、弱めの中火で煮る。","肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。 カレー粉を小鉢の煮汁で溶き、鍋に戻す。醤油とみりんを加える。","うどんを入れ、袋の加熱時間を目安にほぐれるまで煮る。","火を弱め、混ぜ直した水溶き片栗粉を少しずつ加える。全体を混ぜ、ふつふつする火加減で1分ほど煮てとろみをつける。"],"notes":["カレー粉は塩分のない粉を使用する。だし汁やうどんは商品の原材料表示を確認する。"],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P04","id":"4bd16faf-ddeb-5a01-9036-7a064cd11915","name":"白身魚のしょうが煮","proteinSource":"fish","servings":4,"totalMinutes":30,"ingredients":["【主菜】白身魚の切り身 4切れ（約400g）・しょうが 20g","【煮汁】水 300ml・酒 100ml・醤油 大さじ3・みりん 大さじ3・砂糖 大さじ1"],"steps":["しょうがを薄切りにする。魚の表面の水分を拭き、うろこが残っていれば取り除く。","魚が重ならずに入る鍋へ煮汁の材料としょうがを入れ、中火で煮立てる。","魚を入れ、煮汁をスプーンですくって表面にかける。落としぶたをし、弱めの中火で10分ほど煮る。","厚い部分まで火が通ったか確認する。半透明の身が残る場合は加熱を続ける。煮汁が減りすぎた場合は水を少量足す。","魚をくずさないように皿へ移す。煮汁を好みの濃さまで軽く煮詰め、魚にかける。"],"notes":["切り身の厚さにより加熱時間が変わる。骨に注意して食べる。"],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P05","id":"301d1033-036f-5f7c-828c-3433aff913b9","name":"豚肉と根菜のみそ汁","proteinSource":"meat","servings":4,"totalMinutes":40,"ingredients":["【具】豚薄切り肉 250g・大根 250g・にんじん 120g・ごぼう 100g・長ねぎ 1本","【汁】だし汁 1200ml・みそ 60g・油 小さじ2"],"steps":["大根とにんじんは皮をむき、厚さ5mmのいちょう切りにする。ごぼうは洗って薄い斜め切りにし、水にさっとさらして水を切る。長ねぎは小口切りにする。","豚肉を3cm幅に切る。鍋に油を入れて中火にかけ、豚肉をほぐしながら炒める。","大根、にんじん、ごぼうを入れて2分ほど炒め、だし汁を注ぐ。沸いたらアクを取り、弱めの中火で15〜20分煮る。","根菜に竹串がすっと入るやわらかさになったか確認する。肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。","長ねぎを加えて2分煮る。火を弱めてみそを溶き入れ、沸騰させずに温めて火を止める。"],"notes":[],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P06","id":"3a166391-dacf-5ce0-9079-1044175f190f","name":"牛肉の肉じゃが","proteinSource":"meat","servings":4,"totalMinutes":40,"ingredients":["【主菜】牛薄切り肉 300g・じゃがいも 600g・玉ねぎ 2個（約400g）・にんじん 1本（約150g）","【煮汁】水 500ml・醤油 大さじ3・酒 大さじ3・みりん 大さじ3・砂糖 大さじ1","【炒め用】油 小さじ2"],"steps":["じゃがいもは皮と芽を除いて4〜6等分し、水にさらして水を切る。玉ねぎはくし形、にんじんは一口大に切る。牛肉は食べやすい長さに切る。","鍋に油を入れて中火で温め、玉ねぎと牛肉を炒める。肉をほぐしたらじゃがいも、にんじんを加える。","煮汁の材料を加え、沸いたらアクを取り除く。落としぶたをして弱めの中火で20分ほど煮る。","じゃがいもの中心に竹串がすっと入るか確かめる。肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。","火を止めて5分ほどおき、具をくずさないように器に盛る。"],"notes":[],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P07","id":"442961c0-155d-53c8-9a31-97b3fff5ccb6","name":"茶そばと牛肉のフライパン焼き","proteinSource":"noodle","servings":4,"totalMinutes":40,"ingredients":["【主菜】乾燥茶そば 320g・牛薄切り肉 250g・卵 3個・小ねぎ 4本・油 大さじ1","【肉の味付け】醤油 大さじ1・みりん 大さじ1・砂糖 小さじ2","【つゆ】めんつゆ（ストレート）300ml"],"steps":["小ねぎは小口切りにする。卵を溶き、油の一部を入れたフライパンで薄く焼く。卵が固まったら取り出し、細く切る。","牛肉は食べやすい大きさに切る。同じフライパンで肉をほぐしながら炒め、肉の味付けの材料を加える。肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。 汁気が少なくなったら清潔な皿へ取り出す。","茶そばを袋の表示どおりにゆで、流水で洗って十分に水を切る。","フライパンに残りの油を入れ、茶そばの半量を広げて中火で3〜4分焼く。裏側に軽く焼き色がついたら皿に取り、残りも同様に焼く。","そばに牛肉、卵、小ねぎをのせる。めんつゆを別鍋で温め、小鉢に分けて添える。"],"notes":["そば・卵・小麦を含む。めんつゆは濃縮品の場合、表示に従ってストレート相当へ薄める。"],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P08","id":"9adb9288-79b4-5474-80f4-fe5473286fad","name":"牛肉と厚揚げの甘辛煮","proteinSource":"meat","servings":4,"totalMinutes":30,"ingredients":["【主菜】牛薄切り肉 300g・厚揚げ 400g・玉ねぎ 1個（約200g）","【煮汁】水 300ml・醤油 大さじ3・みりん 大さじ3・酒 大さじ2・砂糖 小さじ2"],"steps":["玉ねぎは幅1cmのくし形、厚揚げは2cm角、牛肉は食べやすい長さに切る。","鍋に煮汁の材料と玉ねぎを入れ、中火で沸かす。弱めの中火にして5分煮る。","牛肉を少量ずつほぐして加える。アクを取り、厚揚げを加える。","ふたを少しずらしてのせ、弱火で10分ほど煮る。途中で鍋をゆすり、煮汁を全体に回す。","肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。 玉ねぎがやわらかくなり厚揚げの中心まで熱くなったら、火を止めて器に盛る。"],"notes":[],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P09","id":"06d7ad89-422e-51c9-8788-d0febf2c20c6","name":"鶏肉と野菜のミルク煮","proteinSource":"meat","servings":4,"totalMinutes":40,"ingredients":["【主菜】鶏もも肉 500g・玉ねぎ 1個（約200g）・にんじん 1本（約150g）・しめじ 150g","【煮汁】水 300ml・牛乳 500ml・塩 小さじ1/2・こしょう 少々","【とろみ】薄力粉 大さじ3・バター 20g"],"steps":["玉ねぎは薄切り、にんじんは厚さ5mmの半月切りにする。しめじは石づきを除いてほぐす。鶏肉は3cm角に切る。","鍋にバターを入れて弱めの中火で溶かし、鶏肉を炒める。表面の色が変わったら玉ねぎ、にんじん、しめじを加えて3分ほど炒める。","火を弱めて薄力粉を振り入れ、粉が見えなくなるまで混ぜる。水を少しずつ加え、鍋底から混ぜてなじませる。","沸いたら弱火にし、ふたを少しずらして10〜15分煮る。にんじんがやわらかくなったか確認する。肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。","牛乳、塩、こしょうを加える。弱火で混ぜながら5分ほど温め、とろみがついたら火を止める。"],"notes":["牛乳を加えてからは強く沸騰させない。小麦・乳を含む。"],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P10","id":"aec00d8a-d6d8-5f26-9371-0d18ea4465eb","name":"鶏肉と玉ねぎの卵とじ丼","proteinSource":"egg","servings":4,"totalMinutes":30,"ingredients":["【主菜】鶏もも肉 400g・玉ねぎ 1個（約200g）・卵 6個・炊いたご飯 800g","【煮汁】だし汁 250ml・醤油 大さじ3・みりん 大さじ3・砂糖 小さじ2"],"steps":["玉ねぎは薄切りにする。鶏肉は2cm角に切る。卵は器に割って溶いておく。","広めのフライパンに煮汁の材料と玉ねぎを入れる。中火で煮立て、鶏肉を重ならないように入れる。","弱めの中火で7〜10分煮る。肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。","溶き卵を全体に回し入れる。ふたをして弱火で加熱し、卵の液状の部分がなくなるまで火を通す。","器に温かいご飯を盛り、鶏肉と卵を汁ごとのせる。"],"notes":["卵は半熟で仕上げず、全体を十分に加熱する。"],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P11","id":"e033f6f1-9851-564a-84a2-afbd1bc77a01","name":"玉ねぎ入りハンバーグ","proteinSource":"meat","servings":4,"totalMinutes":40,"ingredients":["【肉だね】合いびき肉 500g・玉ねぎ 1個（約200g）・卵 1個・パン粉 40g・牛乳 60ml・塩 小さじ1/2・こしょう 少々","【加熱用】油 大さじ1・水 100ml","【ソース】ケチャップ 大さじ3・中濃ソース 大さじ2・水 大さじ2"],"steps":["玉ねぎはみじん切りにする。フライパンに油の半量を入れ、玉ねぎが透き通るまで炒める。皿に広げ、冷ましておく。パン粉は牛乳に浸す。","ボウルにひき肉、塩、こしょうを入れて粘りが出るまで混ぜる。冷ました玉ねぎ、卵、パン粉を加えて混ぜ、4等分して厚さ2cmほどの小判形にする。","フライパンに残りの油を入れて中火で温め、肉だねを並べる。3分ほど焼いて裏返し、水100mlを注いでふたをする。","弱火で10〜12分蒸し焼きにする。肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。 厚い部分を確認し、加熱が足りなければ水を少し足して続ける。清潔な皿へ取り出す。","フライパンの余分な脂を取り、ソースの材料を入れて1分ほど煮立てる。ハンバーグにかける。"],"notes":["卵・乳・小麦を含む。見た目や肉汁だけで加熱完了を判断せず、中心温度を確認する。"],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}},{"key":"P12","id":"e38b87ee-e925-54ee-8ba7-8b5d95daeb81","name":"鶏もも肉のしょうゆ煮","proteinSource":"meat","servings":4,"totalMinutes":35,"ingredients":["【主菜】鶏もも肉 600g・しょうが 20g","【煮汁】水 300ml・醤油 大さじ3・酒 大さじ3・みりん 大さじ3・砂糖 大さじ1"],"steps":["しょうがは薄切りにする。鶏肉は余分な脂を除き、厚い部分に包丁を入れて厚みをそろえる。巻かずに広げたまま使う。","鶏肉が重ならず入る鍋に煮汁としょうがを入れ、中火にかける。沸いたら鶏肉を皮を下にして入れる。","弱めの中火にして落としぶたをし、10分煮る。裏返してさらに10分ほど煮る。煮汁が少なくなりすぎたら水を足す。","肉の中心に温度計を当て、75℃以上になってから1分以上加熱する。足りなければ加熱を続ける。 火を止め、煮汁の中で5分ほどおく。","清潔なまな板へ取り出して幅1cmに切る。器に盛り、温かい煮汁をかける。"],"notes":[],"provenance":{"method":"independent_ai_draft","createdAt":"2026-11-07","sourceUrls":[],"cookingTested":false,"nutritionCalculated":false}}]'::jsonb);

