insert into public.recipes (id, household_id, name, category, servings_base, prep_minutes, cook_minutes, protein_source, meta)
select (d->>'id')::uuid, null, d->>'name', 'main', (d->>'servings')::int, 0,
(d->>'totalMinutes')::int, d->>'proteinSource', jsonb_build_object(
'nutrition_catalog_id', 'reviewed-' || lower(d->>'key'), 'side', '',
'ingredients_text', (select string_agg(value, E'\n') from jsonb_array_elements_text(d->'ingredients')),
'steps_text', (select string_agg(value, E'\n') from jsonb_array_elements_text(d->'steps')),
'recipe_notes', d->'notes', 'total_minutes', (d->>'totalMinutes')::int,
'servings_base', (d->>'servings')::int, 'provenance', d->'provenance')
from reviewed_recipe_seed s cross join lateral jsonb_array_elements(s.item) d
on conflict (id) do nothing;

insert into public.recipe_steps (recipe_id, phase, position, text)
select r.id, phase.name, entry.position::int - 1, entry.value
from reviewed_recipe_seed s cross join lateral jsonb_array_elements(s.item) d
join public.recipes r on r.id = (d->>'id')::uuid and r.household_id is null
  and r.meta->>'nutrition_catalog_id' = 'reviewed-' || lower(d->>'key')
cross join lateral (values ('seasoning', d->'ingredients'), ('evening', d->'steps')) phase(name, contents)
cross join lateral jsonb_array_elements_text(phase.contents) with ordinality entry(value, position)
on conflict (recipe_id, phase, position) do nothing;

update public.breakfast_templates set item = '{"sourceKey":"A","name":"納豆ごはんとりんご","minutes":10,"tasks":["温かいごはんを器によそう。納豆は食べる直前に混ぜ、別の小鉢に入れる。","りんごを洗って芯を取り、食べやすい大きさに切って添える。"],"shoppingItems":["米","納豆","りんご"]}'::jsonb where key = 'A';

update public.breakfast_templates set item = '{"sourceKey":"B","name":"チーズトーストとバナナ","minutes":10,"tasks":["食パンにチーズをのせ、トースターの説明書に従って焼く。焦げ始めたら加熱を止める。","バナナの皮をむいて切り、パンと一緒に盛り付ける。"],"shoppingItems":["食パン","スライスチーズ","バナナ"]}'::jsonb where key = 'B';

update public.breakfast_templates set item = '{"sourceKey":"C","name":"鮭フレークごはんと即席みそ汁","minutes":10,"tasks":["温かいごはんに鮭フレークをのせる。","即席みそ汁を商品の表示どおりの湯量で作り、ごはんに添える。"],"shoppingItems":["米","鮭フレーク","即席みそ汁"]}'::jsonb where key = 'C';

update public.breakfast_templates set item = '{"sourceKey":"D","name":"ヨーグルトとシリアルの朝食","minutes":10,"tasks":["ヨーグルトを器に入れ、シリアルを添える。","バナナの皮をむいて輪切りにし、食べる直前に器へ加える。"],"shoppingItems":["ヨーグルト","シリアル","バナナ"]}'::jsonb where key = 'D';

update public.breakfast_templates set item = '{"sourceKey":"E","name":"ツナのりごはん","minutes":10,"tasks":["ツナ缶を開けて汁を切る。焼きのりは手で小さくちぎる。","温かいごはんにツナとのりをのせ、好みで混ぜて食べる。"],"shoppingItems":["米","ツナ缶","焼きのり"]}'::jsonb where key = 'E';

update public.breakfast_templates set item = '{"sourceKey":"F","name":"トーストとゆで卵","minutes":10,"tasks":["パンをトースターの説明書に従って焼く。","市販のゆで卵を商品の表示に従って用意する。ミニトマトを洗い、小さい子どもには縦4等分して添える。"],"shoppingItems":["食パン","ゆで卵（市販品）","ミニトマト"]}'::jsonb where key = 'F';

update public.breakfast_templates set item = '{"sourceKey":"G","name":"しらすごはんとヨーグルト","minutes":10,"tasks":["温かいごはんを器に盛り、釜揚げしらすをのせる。","ヨーグルトを別の器に用意し、一緒に出す。"],"shoppingItems":["米","釜揚げしらす","ヨーグルト"]}'::jsonb where key = 'G';

update public.breakfast_templates set item = '{"sourceKey":"H","name":"チーズパンとりんご","minutes":10,"tasks":["パンとチーズを食べやすい大きさにして皿に並べる。","りんごを洗って芯を取り、薄く切って添える。"],"shoppingItems":["パン","チーズ","りんご"]}'::jsonb where key = 'H';

update public.breakfast_templates set item = '{"sourceKey":"I","name":"コーンフレークと牛乳","minutes":10,"tasks":["バナナの皮をむき、ひと口大に切る。","器にコーンフレークとバナナを入れ、食べる直前に牛乳を注ぐ。"],"shoppingItems":["コーンフレーク","牛乳","バナナ"]}'::jsonb where key = 'I';

update public.breakfast_templates set item = '{"sourceKey":"J","name":"梅のお茶漬け","minutes":10,"tasks":["温かいごはんに、種を取り除いた梅干しとちぎったのりをのせる。","温かいお茶を少しずつ注ぐ。やけどをしない温度まで冷まして食べる。"],"shoppingItems":["米","梅干し","焼きのり","お茶"]}'::jsonb where key = 'J';
